/* Uma entrada por vez, a mais antiga primeiro.

   Uma por execução de propósito. Duas entradas do mesmo SKU processadas em
   paralelo leriam o mesmo saldo antigo e a segunda apagaria a primeira — o
   estoque somaria uma compra só. Como a Base não tem "soma isso aqui", só
   "o estoque agora é X", ler e escrever precisa acontecer em fila. */
const resp = $input.first().json || {};
if (resp.error) throw new Error('Não consegui ler a fila no LiveOps: ' + JSON.stringify(resp.error).slice(0, 300));

const todas = Object.entries(resp || {})
  .filter(([k, v]) => v && typeof v === 'object' && v.status === 'pendente')
  .map(([k, v]) => ({ chave: k, ...v }))
  .sort((a, b) => (Number(a.ts) || 0) - (Number(b.ts) || 0));

if (!todas.length) { console.log('nada na fila'); return []; }

const a = todas[0];
console.log('processando ' + a.quantidade + '× ' + a.sku + ' (' + (todas.length) + ' na fila) — pedida por ' + (a.criadoPor || '?'));
return [{ json: a }];

/* Catálogo e mapa de armazéns.

   O pedido guarda o NOME do armazém ("Estoque ES"), porque nome é o que a
   equipe conhece; a Base quer a chave ("bl_43152"). A tradução é aqui, e o
   nome que não existir mais na Base para o lançamento com motivo — melhor
   recusar do que lançar no armazém errado. */
const cat = $input.first().json || {};
if (cat.status !== 'SUCCESS') throw new Error('Não consegui listar os catálogos: ' + (cat.error_message || 'motivo não informado'));
const inventarios = Object.keys(cat.inventories || {});
if (!inventarios.length) throw new Error('A Base não devolveu nenhum catálogo.');

const arm = $('Base · armazéns (entrada)').first().json || {};
const porNome = {};
(arm.warehouses || []).forEach(w => {
  porNome[String(w.name || '')] = String(w.warehouse_type || '') + '_' + String(w.warehouse_id || '');
});
return [{ json: { inventory_id: inventarios[0], armazensPorNome: porNome } }];

/* Achou o SKU na Base?

   Quando não acha, o pedido NÃO vira erro: vira "sem cadastro na Base", que
   é outra coisa e pede outra ação — alguém precisa cadastrar o produto lá.
   O fluxo antigo mandava um WhatsApp pedindo isso; aqui a situação fica na
   própria tela de quem lançou, junto com o botão de refazer. */
const pedido = $('Fila do LiveOps').first().json;
const r = $input.first().json || {};

if (r.status !== 'SUCCESS') {
  return [[], [{ json: { ...pedido, _falha: 'A Base recusou a busca: ' + (r.error_message || r.error_code || 'motivo não informado') } }]];
}
const achados = Object.keys(r.products || {});
if (!achados.length) {
  return [[], [{ json: { ...pedido, _semCadastro: true } }]];
}
if (achados.length > 1) {
  return [[], [{ json: { ...pedido, _falha: 'Há ' + achados.length + ' produtos com este SKU na Base (' + achados.join(', ') + '). Não dá para saber em qual lançar.' } }]];
}
return [[{ json: { ...pedido, produtoId: achados[0], inventory_id: $('Catálogo e armazéns').first().json.inventory_id } }], []];

/* A conta do lançamento — feita AGORA, com o saldo que a Base acabou de
   devolver, e não com o que a tela mostrava.

   Média ponderada: (saldo × custo atual + quantidade × custo da compra) /
   saldo final.

   Duas guardas que o fluxo antigo não tinha, e as duas doem de verdade:

   1) Saldo negativo. O catálogo tem produto com saldo negativo — vimos -5.
      Com saldo -5, custo 100 e uma compra de 10 a 50, a fórmula dá
      (-500 + 500) / 5 = 0: o produto perde o custo inteiro e passa a valer
      zero no estoque. Quando o saldo atual não é positivo, o custo médio
      novo é o custo desta compra, que é a única informação confiável.

   2) Preço negativo. A fórmula do preço base (preço × 0,88 − 19,95) devolve
      número negativo para qualquer preço abaixo de R$ 22,67 — e preço
      negativo entra na Base e vai para o marketplace. Preço calculado que
      não seja positivo é descartado e o preço antigo permanece. */
const TAXA = 0.88, TARIFA = 19.95;

const pedido = $('Achou na Base?').first().json;
const r = $input.first().json || {};
if (r.status !== 'SUCCESS') {
  return [[], [{ json: { ...pedido, _falha: 'Não consegui ler o produto na Base: ' + (r.error_message || 'motivo não informado') } }]];
}
const dados = (r.products || {})[pedido.produtoId];
if (!dados) {
  return [[], [{ json: { ...pedido, _falha: 'A Base não devolveu os dados do produto ' + pedido.produtoId } }]];
}

const mapa = $('Catálogo e armazéns').first().json.armazensPorNome || {};
const chaveArmazem = mapa[pedido.armazem];
if (!chaveArmazem) {
  return [[], [{ json: { ...pedido, _falha: 'O armazém "' + pedido.armazem + '" não existe mais na Base. Existem: ' + Object.keys(mapa).join(', ') } }]];
}

const saldoAntes = Number((dados.stock || {})[chaveArmazem]) || 0;
const custoAntes = Number(dados.average_cost) || 0;
const qtd = Number(pedido.quantidade) || 0;
const custoCompra = Number(pedido.custo) || 0;
const saldoDepois = saldoAntes + qtd;

let custoDepois;
if (saldoAntes <= 0 || custoAntes <= 0) custoDepois = custoCompra;
else custoDepois = ((saldoAntes * custoAntes) + (qtd * custoCompra)) / saldoDepois;
custoDepois = Math.round(custoDepois * 10000) / 10000;

/* Preço só entra no pacote quando foi pedido E o cálculo deu positivo.
   Campo ausente é a forma de dizer "não mexe" — mandar o preço antigo de
   volta funcionaria, mas gravaria por cima de uma alteração que alguém
   tenha feito na Base entre a leitura e a escrita. */
const precos = {};
let precoBase = null, precoAtacado = null;
if (pedido.precoMl != null) {
  const calc = (Number(pedido.precoMl) * TAXA) - TARIFA;
  if (calc > 0) { precoBase = Math.round(calc * 100) / 100; }
  else console.log('preço ML de ' + pedido.precoMl + ' daria ' + calc.toFixed(2) + ' — descartado, o preço antigo fica');
}
if (pedido.precoAtacado != null) {
  const v = Number(pedido.precoAtacado);
  if (v > 0) precoAtacado = Math.round(v * 100) / 100;
}

/* Os ids das tabelas de preço saem do próprio produto: a primeira é a base
   e a segunda o atacado no cadastro atual. Cravar número aqui quebraria em
   silêncio no dia em que a Base renumerar as tabelas. */
const idsPreco = Object.keys(dados.prices || {});
if (precoBase != null && idsPreco[0]) precos[idsPreco[0]] = precoBase;
if (precoAtacado != null && idsPreco[1]) precos[idsPreco[1]] = precoAtacado;

const pacote = {
  inventory_id: pedido.inventory_id,
  product_id: String(pedido.produtoId),
  stock: { [chaveArmazem]: saldoDepois },
  average_cost: custoDepois
};
if (Object.keys(precos).length) pacote.prices = precos;

console.log(pedido.sku + ': ' + saldoAntes + ' → ' + saldoDepois + ' un. | custo '
  + custoAntes.toFixed(2) + ' → ' + custoDepois.toFixed(2)
  + (precoBase != null ? (' | preço base → ' + precoBase.toFixed(2)) : '')
  + (saldoAntes < 0 ? '  ⚠ saldo estava negativo, média partiu desta compra' : ''));

return [[{ json: {
  pacote,
  resultado: {
    produtoId: String(pedido.produtoId),
    nomeProduto: (dados.text_fields && dados.text_fields.name) || dados.name || '',
    estoqueAntes: saldoAntes, estoqueDepois: saldoDepois,
    custoAntes: custoAntes || null, custoDepois: custoDepois,
    precoBase: precoBase, precoAtacadoAplicado: precoAtacado
  },
  chave: pedido.chave
} }], []];

/* Só marca como lançado se a Base confirmou. Um PATCH escrito a partir de
   uma resposta que não veio SUCCESS diria que deu certo quando não deu, e a
   mercadoria ficaria fora do estoque com o pedido marcado como resolvido —
   o pior dos dois mundos, porque ninguém volta a olhar. */
const r = $input.first().json || {};
const base = $('Calcular o lançamento').first().json;
const carimbo = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });

if (r.status !== 'SUCCESS') {
  return [{ json: { chave: base.chave, patch: {
    status: 'erro',
    erro: 'A Base recusou o lançamento: ' + (r.error_message || r.error_code || 'motivo não informado'),
    processadoEm: carimbo, _by: 'n8n'
  } } }];
}
return [{ json: { chave: base.chave, patch: { ...base.resultado, status: 'lancado', erro: null, processadoEm: carimbo, _by: 'n8n' } } }];

/* Os dois desfechos que não mexem na Base. Ambos voltam para a tela de quem
   lançou, com o motivo escrito — é lá que a pessoa decide o que fazer. */
const p = $input.first().json;
const carimbo = new Date().toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo' });
return [{ json: { chave: p.chave, patch: {
  status: p._semCadastro ? 'sem_cadastro' : 'erro',
  erro: p._semCadastro
    ? ('O SKU ' + p.sku + ' não existe no catálogo da Base. Cadastre o produto lá e refaça a entrada.')
    : p._falha,
  processadoEm: carimbo, _by: 'n8n'
} } }];
